import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Implementing Ceph at GMUs College of Engineering and Computing","description":"","frontmatter":{"title":"Implementing Ceph at GMUs College of Engineering and Computing","date":"2026-04-21T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["Ceph","cephfs","高校存储","distributed storage","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Implementing_Ceph_at_GMU_s_College_of_Engineering_and_Computing.md","filePath":"posts/2026/Implementing_Ceph_at_GMU_s_College_of_Engineering_and_Computing.md","lastUpdated":1780459816000}'),l={name:"posts/2026/Implementing_Ceph_at_GMU_s_College_of_Engineering_and_Computing.md"};function r(n,e,s,h,p,g){return t(),o("div",null,[...e[0]||(e[0]=[i('<h2 id="演讲者与机构背景" tabindex="-1">演讲者与机构背景 <a class="header-anchor" href="#演讲者与机构背景" aria-label="Permalink to &quot;演讲者与机构背景&quot;">​</a></h2><p>本次演讲由 Dan O&#39;Brien 主讲，他就职于乔治梅森大学（George Mason University，GMU）工程与计算学院，自 2018 年起负责 Linux 系统管理工作，同时承担 Ceph 存储集群的运维管理职责。</p><p>乔治梅森大学位于弗吉尼亚州费尔法克斯，在校学生约 4万人。工程与计算学院是全校最大的学术单位，学生人数超过 1 万。IT 架构上，学校采用分布式 IT 模式：中央 IT 负责网络服务、身份认证及数据中心运营；研究计算办公室运营高性能计算集群；分布式 IT 团队（即演讲者所在团队）主要管理教学用术系统、计算机实验室及教职工桌面支持。</p><p>基础设施以 Dell 服务器为主，操作系统以 RHEL/Rocky Linux 为主，服务器机房具备 10Gigabit Ethernet 骨干网络互联。</p><h2 id="存储挑战-引入-ceph-的背景" tabindex="-1">存储挑战：引入 Ceph 的背景 <a class="header-anchor" href="#存储挑战-引入-ceph-的背景" aria-label="Permalink to &quot;存储挑战：引入 Ceph 的背景&quot;">​</a></h2><p>在引入 Ceph 之前，该学院面临多项典型的存储管理痛点：</p><ul><li><strong>数据分散</strong>：大量数据存放在 VM 的虚拟磁盘上，缺乏统一管理</li><li><strong>high availability 不足</strong>：并非所有平台都具备高可用保障</li><li><strong>scalability 差</strong>：现有架构难以横向扩展</li><li><strong>生命周期管理混乱</strong>：存在大量 EOL 操作系统仍在运行，数据管理生命周期极为临时化</li><li><strong>用户群体复杂</strong>：兼职教师、在读学生、毕业后返校读研的学生等，用户状态频繁变化，数据归属难以追踪</li></ul><h2 id="当前-ceph-集群配置" tabindex="-1">当前 Ceph 集群配置 <a class="header-anchor" href="#当前-ceph-集群配置" aria-label="Permalink to &quot;当前 Ceph 集群配置&quot;">​</a></h2><p>目前的 Ceph 集群通过 cephadm 容器化部署，规模较小但功能完整：</p><ul><li><strong>存储节点</strong>：3 个 storage node</li><li><strong>服务节点</strong>：2 个，运行各类 daemon 和 gateway</li><li><strong>OSD</strong>：25 个，原始存储容量 128 TB</li><li><strong>存储介质</strong>：SD 作为缓存层，HDD 作为主存储（当前子集群全为 HDD）</li><li><strong>网络</strong>：10 Gigabit 骨干，存储节点配置 LACP bonding，实现 20 Gbps 双向带宽；通过 VLAN 隔离 Ceph 后端网络与 iSCSI 网络</li></ul><h2 id="ceph-的引入历程" tabindex="-1">Ceph 的引入历程 <a class="header-anchor" href="#ceph-的引入历程" aria-label="Permalink to &quot;Ceph 的引入历程&quot;">​</a></h2><p>最初引入 Ceph 是为了配合 OpenStack 实验。团队原本考虑使用 NFS，但发现配置复杂，转而搭建单节点 Ceph 集群（仅几块 HDD，无 SD），因为 OpenStack 原生支持 Ceph 作为存储后端，集成更为顺畅。目前已有多个 OpenStack 实例共用同一套 Ceph 后端。</p><p>Ceph 2024 纽约峰会（Ceph Day 2024 NYC）成为重要转折点，团队在会后正式决定全面投入 Ceph，并在会后补充了 WAL（Write-Ahead Log）和 RocksDB 的 SD 配置。</p><h2 id="cephfs-替代-nfs-的主目录迁移" tabindex="-1">cephfs 替代 NFS 的主目录迁移 <a class="header-anchor" href="#cephfs-替代-nfs-的主目录迁移" aria-label="Permalink to &quot;cephfs 替代 NFS 的主目录迁移&quot;">​</a></h2><h3 id="问题起因" tabindex="-1">问题起因 <a class="header-anchor" href="#问题起因" aria-label="Permalink to &quot;问题起因&quot;">​</a></h3><p>原有 3 台 NFS 服务器各自独立，主目录随机分配，依赖复杂的 automount 脚本定位挂载点，缺乏 high availability 保障。</p><h3 id="数据摸底工具" tabindex="-1">数据摸底工具 <a class="header-anchor" href="#数据摸底工具" aria-label="Permalink to &quot;数据摸底工具&quot;">​</a></h3><p>迁移前，演讲者开发了一套自制库存工具，遍历三台 NFS 服务器，按用户 ID 收集主目录大小、文件数量等统计信息，并整合课程注册信息与在职/在读状态，写入 CSV 后导入 SQLite 数据库，支持精准查询定向迁移目标。</p><h3 id="迁移触发事件" tabindex="-1">迁移触发事件 <a class="header-anchor" href="#迁移触发事件" aria-label="Permalink to &quot;迁移触发事件&quot;">​</a></h3><p>2025 年 5 月，计算机科学学生大规模采用 VS Code，导致 NFS 服务器在期末作业截止前出现严重 IO 压力：约 200 名学生同时在线，每台 Zeus 系统约 100 个并发用户，超过一半使用 Visual Studio，每秒产生 50KB 至 1MB 的 IO，Dell PERC 卡的 NFS 服务器不堪重负。</p><h3 id="cephfs-配置" tabindex="-1">cephfs 配置 <a class="header-anchor" href="#cephfs-配置" aria-label="Permalink to &quot;cephfs 配置&quot;">​</a></h3><ul><li>单一 cephfs 文件系统</li><li>多个 MDS，配置热备（hot standby）</li><li>按 subvolume 组织，兼顾管理便利性与数据安全隔离</li><li>针对不同数据类型创建独立 pool</li></ul><h3 id="迁移进展" tabindex="-1">迁移进展 <a class="header-anchor" href="#迁移进展" aria-label="Permalink to &quot;迁移进展&quot;">​</a></h3><ul><li>按主目录数量：已完成约 95%（约 16,000 个在 cephfs，约 800 个仍在 NFS）</li><li>按数据量：仅完成约 50%（剩余均为&quot;硬骨头&quot;——大体积目录）</li><li>迁移脚本核心为 rsync，跳过 Visual Studio 缓存目录（<code>.cache</code>、JetBrains 缓存等）</li><li>实测效果显著：部分主目录迁移后体积缩减 90%（100MB → 10MB）；迁移超过 3TB 数据后，cephfs 中实际仅占用约 1.2TB，推测 NFS 的 4K block与 cephfs 的 512B block 差异也贡献了可观的空间节省</li><li>当前 cephfs 中约有 2400 万个文件</li></ul><h3 id="迁移效果" tabindex="-1">迁移效果 <a class="header-anchor" href="#迁移效果" aria-label="Permalink to &quot;迁移效果&quot;">​</a></h3><p>自 CS 学生主目录迁移至 cephfs 后，期末考试和期中考试期间<strong>零宕机</strong>，CS 教职工对此高度满意。</p><h2 id="quota-管理" tabindex="-1">Quota 管理 <a class="header-anchor" href="#quota-管理" aria-label="Permalink to &quot;Quota 管理&quot;">​</a></h2><p>为防止 cephfs 重蹈 NFS 混乱局面，团队基于库存数据制定了 quota 策略：</p><ul><li><strong>学生</strong>：10 GB / 用户（原计划 5 GB，经上级建议调整）</li><li><strong>教职工</strong>：250 GB + 50 万文件数上限</li><li>主目录创建或迁移时自动设置 quota</li><li>提供自助临时提额脚本，用户无需开工单即可申请短期扩容</li><li>登录时展示当前使用率：75% 显示黄色警告，90% 及以上显示红色警告</li></ul><h2 id="其他-ceph-功能应用" tabindex="-1">其他 Ceph 功能应用 <a class="header-anchor" href="#其他-ceph-功能应用" aria-label="Permalink to &quot;其他 Ceph 功能应用&quot;">​</a></h2><h3 id="nfs-gateway" tabindex="-1">NFS Gateway <a class="header-anchor" href="#nfs-gateway" aria-label="Permalink to &quot;NFS Gateway&quot;">​</a></h3><p>部分老旧系统（如仍运行 RHEL 6 的节点）无法直接挂载 cephfs，通过 NFS gateway 转接访问。此外，部分 VM 所在的旧 oVirt 集群因网络架构限制无法直接访问存储网络，同样依赖 NFS gateway。</p><h3 id="block-storage-rbd" tabindex="-1">Block Storage（RBD） <a class="header-anchor" href="#block-storage-rbd" aria-label="Permalink to &quot;Block Storage（RBD）&quot;">​</a></h3><p>oVirt 集群使用 Ceph RBD 作为 block storage 后端。正在评估新 oVirt 集群（RHEL 9 节点）直接使用 Ceph managed block storage，但尚未完全调通。</p><h3 id="object-storage-rgw" tabindex="-1">Object Storage（RGW） <a class="header-anchor" href="#object-storage-rgw" aria-label="Permalink to &quot;Object Storage（RGW）&quot;">​</a></h3><p>已搭建 RGW（RADOS Gateway），主要探索与 OpenStack Swift 的集成。文档中未明确说明 Ceph RGW 可直接替代 Swift，导致初期配置走了弯路。目前已部署但使用有限，计划用于主目录数据的归档存储。</p><h3 id="web内容存储" tabindex="-1">Web内容存储 <a class="header-anchor" href="#web内容存储" aria-label="Permalink to &quot;Web内容存储&quot;">​</a></h3><p>计划将分散在各 VM 上的 Web 内容统一迁移至 cephfs subvolume，配合反向代理架构，实现内容存储与交付解耦，提升安全性（Web 服务器不再暴露于公网子网）、简化备份与容量扩展。</p><h2 id="未来规划" tabindex="-1">未来规划 <a class="header-anchor" href="#未来规划" aria-label="Permalink to &quot;未来规划&quot;">​</a></h2><ol><li><strong>完成 NFS 迁移</strong>：剩余约 800 个主目录需与教职工高接触沟通确认数据去留</li><li><strong>扩展 Ceph 集群</strong>：退役 oVirt 和 NFS 的硬件资源将并入 Ceph 集群</li><li><strong>升级至 Tentacle</strong>：关注 iSCSI gateway 在 Squid/Tentacle 版本中的演进，以及 Samba 与 Windows Active Directory 集成能力</li><li><strong>专用 SD tier</strong>：计划建立独立 SSD tiering 层（受预算制约）</li><li><strong>存储节点与服务节点分离</strong>：gateway 等服务节点与 OSD 节点完全分离</li><li><strong>erasure coding</strong>：节点数达到 5 个后启用 erasure coding，降低存储开销</li><li><strong>MDS 基础设施强化</strong>：主要使用场景已从 OpenStack block storage 转变为约 1万名学生的主目录服务，需相应加强 MDS 配置</li><li><strong>scheduled snapshots</strong>：应对期末高峰期&quot;误删文件&quot;的求助工单，提供比&quot;恢复到昨天备份&quot;更细粒度的恢复能力</li><li><strong>异地复制</strong>：计划搭建第二套 Ceph 集群实现数据复制</li><li><strong>Storage as a Service</strong>：为教职工提供托管存储服务，替代不受管控的 NAS 设备，解决安全隐患</li></ol><h2 id="q-a-要点" tabindex="-1">Q&amp;A 要点 <a class="header-anchor" href="#q-a-要点" aria-label="Permalink to &quot;Q&amp;A 要点&quot;">​</a></h2><p><strong>Q：是否计划提供 S3 兼容的对象存储服务？</strong></p><p>A：完全在计划之中。原本引入 OpenStack 的目的之一就是为学生提供内部云资源（含虚拟机和对象存储）。演讲者同时分享了一个 AWS 成本失控的案例：一名学生因 RDS 性能不佳不断升配，另一团队使用 16xlarge GPU 实例运行 7 天才触发预算告警，累计损失约 2 万美元。这充分说明建设内部基础设施、为不熟悉云计费模型的学生提供可控环境的必要性。</p><p><strong>Q：高峰期并发写入规模？</strong></p><p>A：约 200 名学生同时活跃登录并进行编码操作，全部主目录均在 cephfs 上。</p><p><strong>Q：主目录总量？</strong></p><p>A：初始约 3 万个，经归档清理后降至约 1.5 万个。</p>',47)])])}const u=a(l,[["render",r]]);export{d as __pageData,u as default};
